namespace sv_31d413745aeb4a3695dbb5c65f21ad05.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that holds the currently selected warehouse and notifies
/// subscribers when it changes.  Scoped lifetime = one instance per circuit,
/// so each browser tab (each warehouse manager) gets independent state.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    public string CurrentWarehouseId { get; private set; } = AvailableWarehouses[0].Id;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == CurrentWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (warehouseId == CurrentWarehouseId)
            return;

        CurrentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_31d413745aeb4a3695dbb5c65f21ad05.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the current warehouse.
/// Supports timed polling that any component can start/stop, and notifies ALL
/// subscribers when new data arrives — even those that didn't trigger the poll.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activePollers;

    public int LowStockCount { get; private set; }

    /// <summary>
    /// Fired on any thread when new alert data arrives.
    /// Subscribers must wrap StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnChange;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>Simulates a database query — returns a random 0-15 count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begins 10-second polling for the current warehouse. Reference-counted so
    /// multiple components calling Start only creates one timer; polling stops
    /// only when all components have called Stop.
    /// </summary>
    public void StartPolling()
    {
        _activePollers++;
        if (_activePollers == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void StopPolling()
    {
        _activePollers = Math.Max(0, _activePollers - 1);
        if (_activePollers == 0)
        {
            StopTimer();
        }
    }

    /// <summary>Fetch once immediately (used on init or warehouse switch).</summary>
    public async Task RefreshAsync()
    {
        LowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnChange?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Initial fetch right away
        await RefreshAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                LowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
                OnChange?.Invoke();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / stop
        }
    }

    private void OnWarehouseChanged()
    {
        // When the warehouse changes, refresh immediately so all subscribers
        // see data for the new warehouse.
        _ = RefreshAsync();
    }

    private void StopTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopTimer();
    }
}

