@using sv_31d413745aeb4a3695dbb5c65f21ad05.Services
@inject WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label text-light mb-1 small">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

.warehouse-selector {
    padding: 0.5rem 1rem;
}

.warehouse-selector .form-select {
    background-color: rgba(255, 255, 255, 0.1);
    color: white;
    border-color: rgba(255, 255, 255, 0.25);
}

.warehouse-selector .form-select option {
    background-color: #1b1b32;
    color: white;
}

@using sv_31d413745aeb4a3695dbb5c65f21ad05.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.LowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.LowStockCount</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnChange -= _handler;
        }
    }
}

