@using sv_31d413745aeb4a3695dbb5c65f21ad05.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card shadow-sm">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Selected Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseName</p>
                <small class="text-muted">ID: @WarehouseState.CurrentWarehouseId</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card shadow-sm @AlertCardClass">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Low Stock Alerts</h5>
                <p class="display-4 @AlertTextClass">@AlertService.LowStockCount</p>
                <small class="text-muted">Items below minimum level</small>
            </div>
        </div>
    </div>

    <div class="col-md-4">
        <div class="card shadow-sm">
            <div class="card-body text-center">
                <h5 class="card-title text-muted">Polling Status</h5>
                <p class="display-6">
                    <span class="badge bg-success">● Live</span>
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    private string AlertCardClass =>
        AlertService.LowStockCount > 10 ? "border-danger" :
        AlertService.LowStockCount > 5 ? "border-warning" : "";

    private string AlertTextClass =>
        AlertService.LowStockCount > 10 ? "text-danger" :
        AlertService.LowStockCount > 5 ? "text-warning" : "text-success";

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertService.OnChange += _alertHandler;

        // Start polling when dashboard becomes visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        // Stop polling when the user navigates away
        AlertService.StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertService.OnChange -= _alertHandler;
    }
}

